{"implementation": "def solve(case):
    if "nodes" not in case:
        raise ValueError("Missing required field: nodes")
    if "core_distance" not in case:
        raise ValueError("Missing required field: core_distance")
    if "distances" not in case:
        raise ValueError("Missing required field: distances")

    nodes = list(case["nodes"])
    core_dist = case["core_distance"]
    distances = case["distances"]
    n = len(nodes)

    if n == 0:
        raise ValueError("nodes must be non-empty")

    for node in nodes:
        if node not in core_dist:
            raise ValueError(f"core_distance missing for node: {node}")

    mr_edges = []
    for entry in distances:
        if len(entry) != 3:
            raise ValueError(f"Invalid distance entry: {entry}")
        a, b, d = entry[0], entry[1], entry[2]
        if a not in core_dist:
            raise ValueError(f"Node in distances not in core_distance: {a}")
        if b not in core_dist:
            raise ValueError(f"Node in distances not in core_distance: {b}")
        u, v = (a, b) if a <= b else (b, a)
        mr = max(core_dist[a], core_dist[b], d)
        mr_edges.append((mr, u, v))

    mr_edges.sort(key=lambda e: (e[0], e[1], e[2]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            nxt = parent[x]
            parent[x] = root
            x = nxt
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for mr, u, v in mr_edges:
        if union(u, v):
            mst_edges.append({"u": u, "v": v, "weight": mr})
            total_weight += mr
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) < n - 1:
        raise ValueError("Graph is disconnected: cannot construct MST")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
